import {shuttersView,shuttersPosition,shutterWays,validShuttersSource,readableShutterNote,startShutters,rollShutters,selectShutter,clearShutters,closeShutters,showShutterWays,explainShutters,keepShutterNote,resumeShutters,removeShutterRecord} from './shutters-core.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let visit=null;
export const resetShuttersVisit=()=>{visit=null;};
export const gamesTableNav=active=>`<nav class="games-table-nav" aria-label="Games Table"><a href="#orchard/games"${active==='pile'?' aria-current="page"':''}>Seed Pile · with Bramble</a><a href="#orchard/games/shutters"${active==='shutters'?' aria-current="page"':''}>Shutters · solo</a><a href="#orchard/games/rows"${active==='rows'?' aria-current="page"':''}>Ribbon Rows · with Bramble</a></nav>`;
const dice=faces=>`<div class="shutter-dice" role="img" aria-label="${faces.join(' plus ')}${faces.length===2?` makes ${faces[0]+faces[1]}`:''}">${faces.map(n=>`<span class="shutter-die"><span class="shutter-pips" aria-hidden="true">${Array.from({length:9},(_,i)=>`<i${({1:[4],2:[0,8],3:[0,4,8],4:[0,2,6,8],5:[0,2,4,6,8],6:[0,2,3,5,6,8]})[n].includes(i)?' class="ink"':''}></i>`).join('')}</span><span class="shutter-face">${n}</span></span>`).join('')}</div>`;
function tiles(size,open,selected,interactive=false){return `<div class="shutter-tiles">${Array.from({length:size},(_,i)=>i+1).map(n=>{
 const status=!open.includes(n)?'closed':selected.includes(n)?'selected':'open';
 return interactive?`<button type="button" class="shutter-tile ${status}" data-shutter-tile="${n}" aria-label="${n}, ${status}" aria-pressed="${status==='selected'}" aria-describedby="shutter-sum"${status==='closed'?' disabled':''}><span>${n}</span><small>${status==='closed'?'shut':status==='selected'?'chosen':'open'}</small></button>`:`<div class="shutter-tile ${status}"><span>${n}</span><small>${status==='closed'?'shut':status==='selected'?'chosen':'open'}</small></div>`;
 }).join('')}</div>`;}
const outcome=g=>{const p=shuttersPosition(g);return !p?'Earlier round':p.phase==='won'?g.source.won:p.phase==='blocked'?g.source.blocked:`${p.open.length} shutters open${p.phase==='choose'?`; roll ${p.target}`:''}`;};
function setup(v){const size=v.current?.source.size??6;return `<header class="shutter-heading"><p>Bramble’s ribbon-tied box</p><h1 id="shutter-title" tabindex="-1">Shutters</h1><p>“This one is just you and the dice,” says Bramble. “Find different ways to make the same number.”</p></header><div class="shutter-wood shutter-preview" aria-hidden="true">${tiles(6,[1,2,3,4,5,6],[])}${dice([3,4])}</div><form data-shutter-start><label>Choose a box<select name="size"><option value="6"${size===6?' selected':''}>Little box · 1 to 6</option><option value="9"${size===9?' selected':''}>Full box · 1 to 9</option></select></label><p>Roll, choose open numbers that add to your roll, then shut them. Can you shut the whole box?</p><button class="primary" type="submit">Open the box</button>${v.current?'<button type="button" data-shutter-back>Return to our waiting round</button>':''}</form>`;}
function history(r){if(!r)return '';return `<details class="shutter-history"><summary>Earlier rounds and notes</summary><p>No scores are added up. Download a copy from Grown-up notes before removing anything you want to keep.</p>${r.earlier.map((g,i)=>shuttersPosition(g)?`<div class="shutter-record"><p>${esc(g.source.title)}<br>${esc(outcome(g))}</p><button type="button" data-shutter-resume="${i}">Resume</button><button type="button" data-shutter-remove="earlier:${i}">Remove round</button></div>`:'<p>An earlier record stays unchanged in your notes download.</p>').join('')}${r.notes.map((n,i)=>readableShutterNote(n)?`<div class="shutter-record"><p>${esc(n.text||'A round we played.')}<br><small>${esc(outcome(n.game))}${n.game.support.length?' · supplied help was available':''}</small></p><button type="button" data-shutter-remove="notes:${i}">Remove note</button></div>`:'<p>An earlier note stays unchanged in your download.</p>').join('')}<a href="#notes">Download from Grown-up notes</a></details>`;}
function board(g){
 const p=shuttersPosition(g),playing=p.phase==='choose',ended=['won','blocked'].includes(p.phase);
 const rolled=`You rolled ${p.faces.join(' and ')}${p.faces.length===2?`, which make ${p.target}`:''}.`;
 const message=p.phase==='won'?g.source.won:p.phase==='blocked'?`${rolled} ${g.source.blocked}`:playing?`${rolled} Choose open shutters to match the roll.`:'Ready for the next roll?';
 return `<header class="shutter-heading"><h1 id="shutter-title" tabindex="-1">${esc(g.source.title)}</h1><p>${esc(g.source.rule)}</p></header><div class="shutter-wood">${tiles(g.source.size,p.open,g.selected,playing)}<div class="shutter-roll">${p.faces.length?`<div><p>${playing||p.phase==='blocked'?'Your roll':'Last roll'}</p>${dice(p.faces)}</div>`:'<p>The shutters are open. Your first roll is waiting.</p>'}${playing?`<div class="shutter-total"><span>Your chosen numbers</span><strong>${g.selected.length?g.selected.join(' + '):'None yet'}${g.selected.length?` = ${p.selectedTotal}`:''}</strong><span>Match ${p.target}</span></div>`:''}</div></div><h2 id="shutter-turn" tabindex="-1">${esc(message)}</h2>${playing?`<p id="shutter-sum" role="status" aria-live="polite" tabindex="-1">${!g.selected.length?`0 chosen; ${p.target} needed. Tap shutters to choose them, then tap again to put one back.`:p.selectedTotal===p.target?`${p.selectedTotal} chosen; ${p.target} needed. Ready to shut them?`:`${p.selectedTotal} chosen; ${p.target} needed. You can change any chosen shutter.`}</p><div class="shutter-actions"><button class="primary" type="button" data-shutter-close${!g.selected.length||p.selectedTotal!==p.target?' disabled':''}>Shut chosen numbers</button><button type="button" data-shutter-clear${!g.selected.length?' disabled':''}>Clear my choice</button></div><button type="button" data-shutter-ways>Show ways to make this roll</button>${visit.ways?`<aside class="shutter-help"><h3>Bramble shows some ways</h3><p>These are supplied examples. Choose any way you like.</p><ul>${shutterWays(p.open,p.target).map(xs=>`<li>${xs.join(' + ')} = ${p.target}</li>`).join('')}</ul></aside>`:''}`:p.phase==='roll'?`<p>The open numbers add to <strong>${p.open.reduce((a,b)=>a+b,0)}</strong>. ${p.dice===1?'That is six or less: roll one die.':'That is more than six: roll two dice.'}</p><button class="primary" type="button" data-shutter-roll>Roll ${p.dice===1?'one die':'two dice'}</button>`:'<p>The dice can stop a thoughtful plan. A fresh box brings different choices.</p>'}${ended?`<form data-shutter-note><label>A thought to keep <span>(optional)</span><textarea name="note" maxlength="1000" rows="2" placeholder="I tried… I noticed…"${g.noteKept?' disabled':''}></textarea></label><button type="submit"${g.noteKept?' disabled':''}>${g.noteKept?'Note kept':'Keep a round note'}</button></form>`:''}<div class="shutter-actions"><button type="button" data-shutter-new>New round / change box</button><button type="button" data-shutter-explain>Bramble explains</button></div><details><summary>How this round went</summary>${g.moves.length?`<ol>${g.moves.map(m=>`<li>${m.kind==='roll'?`Rolled ${m.faces.join(' + ')}${m.faces.length===2?` = ${m.faces[0]+m.faces[1]}`:''}`:`Shut ${m.tiles.join(', ')}`}.</li>`).join('')}</ol>`:'<p>No dice rolled yet.</p>'}</details>`;
}
function lesson(v){const l=v.root?.lesson;if(!validShuttersSource(l?.source)||!Number.isInteger(l.step)||l.step<0||l.step>3)return '<p>This earlier explanation is unavailable. Your round stays as it was.</p><button type="button" data-shutter-back>Return to our round</button>';
 const f=l.source.frames[l.step];return `<header class="shutter-heading"><h1 id="shutter-title" tabindex="-1">Bramble explains</h1><p>An example with the ${l.source.size===6?'little':'full'} box. Your waiting round stays as it was.</p></header><div class="shutter-wood">${tiles(l.source.size,f.open,f.selected)}${dice(f.faces)}</div><p class="shutter-thought" id="shutter-thought" tabindex="-1">${esc(f.text)}</p><nav class="shutter-actions" aria-label="Shutters explanation"><button type="button" data-shutter-step="${l.step-1}"${l.step===0?' disabled':''}>Back</button><span>Thought ${l.step+1} of 4</span>${l.step<3?`<button class="primary" type="button" data-shutter-step="${l.step+1}">Next thought</button>`:''}</nav><button type="button" data-shutter-back>Return to our waiting round</button>`;
}
export function shuttersPage(state,owner){
 if(!visit||visit.state!==state||visit.owner!==owner)visit={state,owner,page:'game',ways:false,remove:null,message:''};
 const v=shuttersView(state);
 return `<section class="shutters-page" data-shutters-root><a class="back" href="#orchard">Back to the Orchard</a>${gamesTableNav('shutters')}${v.unsupported||v.root?.current&&!v.current?'<p class="shutter-warning">An earlier Shutters record stays unchanged in your download. Opening a new box will keep that record.</p>':''}${visit.page==='lesson'?lesson(v):visit.page==='setup'||!v.current?setup(v):board(v.current)}${visit.remove?'<div class="shutter-confirm" role="group" aria-label="Remove this record?"><p>Remove only this record? Download a copy first if you want to keep it.</p><button type="button" data-shutter-confirm>Remove this record</button><button type="button" data-shutter-cancel>Keep it</button></div>':''}<p id="shutter-status" role="status" tabindex="-1">${esc(visit.message)}</p>${!v.unsupported?history(v.root):''}<p class="tiny">No timer or running score. Leave and return whenever you like.</p></section>`;
}
export function shuttersNotes(state){if(!Object.hasOwn(state,'shutters'))return '';const v=shuttersView(state);return `<details class="panel"><summary>Shutters: number choices and round notes</summary><p>Dice outcomes are not a math level. Supplied combinations and explanations stay separate from choices.</p><p>${esc(v.current?outcome(v.current):v.unsupported||v.root?.current!==null?'Earlier unsupported work stays in the download.':'No round is waiting. Earlier rounds and notes stay in your download.')}</p><a href="#orchard/games/shutters">Return to Shutters</a></details>`;}
export function bindShutters(state,ctx){
 const root=document.querySelector('[data-shutters-root]');if(!root||!visit)return;
 const captured=visit,owner=ctx.explorerId(),rootRef=state.shutters;
 const live=()=>root.isConnected&&document.querySelector('[data-shutters-root]')===root&&location.hash==='#orchard/games/shutters'&&visit===captured&&ctx.isActive()&&ctx.explorerId()===owner&&visit.state===state&&state.shutters===rootRef;
 const render=(selector='#shutter-turn')=>{ctx.render();ctx.focus(selector);};
 const act=(fn,selector='#shutter-turn')=>{
  if(!live())return;visit.message='';
  if(!fn()){const el=root.querySelector('#shutter-status');el.textContent=shuttersView(state).unsupported?'This earlier record cannot be replaced safely here. Download a copy of your notes, then use a separate explorer for a fresh box. Nothing was changed.':'This change cannot fit safely in your notes. Your work is unchanged. Download a copy, then remove chosen earlier rounds or notes to free space. A separate explorer can start fresh.';el.focus();return;}
  visit.remove=null;ctx.save();render(selector);
 };
 root.querySelector('[data-shutter-start]')?.addEventListener('submit',e=>{e.preventDefault();if(!live())return;const size=Number(new FormData(e.target).get('size'));act(()=>startShutters(state,size,ctx.canExport)&&((visit.page='game'),(visit.ways=false),true));});
 root.querySelector('[data-shutter-roll]')?.addEventListener('click',()=>act(()=>rollShutters(state,ctx.canExport)&&((visit.ways=false),true)));
 root.querySelectorAll('[data-shutter-tile]').forEach(b=>b.onclick=()=>act(()=>selectShutter(state,Number(b.dataset.shutterTile),ctx.canExport),`[data-shutter-tile="${b.dataset.shutterTile}"]`));
 root.querySelector('[data-shutter-clear]')?.addEventListener('click',()=>act(()=>clearShutters(state,ctx.canExport),'#shutter-sum'));
 root.querySelector('[data-shutter-close]')?.addEventListener('click',()=>act(()=>closeShutters(state,ctx.canExport)&&((visit.ways=false),true)));
 root.querySelector('[data-shutter-ways]')?.addEventListener('click',()=>act(()=>showShutterWays(state,ctx.canExport)&&((visit.ways=true),true),'#shutter-sum'));
 root.querySelector('[data-shutter-new]')?.addEventListener('click',()=>{if(live()){visit.page='setup';visit.ways=false;visit.remove=null;render('#shutter-title');}});
 root.querySelector('[data-shutter-back]')?.addEventListener('click',()=>{if(live()){visit.page='game';visit.ways=false;visit.remove=null;render('#shutter-title');}});
 root.querySelector('[data-shutter-explain]')?.addEventListener('click',()=>act(()=>explainShutters(state,0,ctx.canExport)&&((visit.page='lesson'),true),'#shutter-title'));
 root.querySelectorAll('[data-shutter-step]').forEach(b=>b.onclick=()=>act(()=>explainShutters(state,Number(b.dataset.shutterStep),ctx.canExport),'#shutter-thought'));
 root.querySelector('[data-shutter-note]')?.addEventListener('submit',e=>{e.preventDefault();act(()=>keepShutterNote(state,new FormData(e.target).get('note'),ctx.canExport)&&((visit.message='Your round note is kept.'),true),'#shutter-status');});
 root.querySelectorAll('[data-shutter-resume]').forEach(b=>b.onclick=()=>act(()=>resumeShutters(state,Number(b.dataset.shutterResume),ctx.canExport)&&((visit.page='game'),(visit.ways=false),true),'#shutter-title'));
 root.querySelectorAll('[data-shutter-remove]').forEach(b=>b.onclick=()=>{if(live()){visit.remove=b.dataset.shutterRemove;render('[data-shutter-cancel]');}});
 root.querySelector('[data-shutter-cancel]')?.addEventListener('click',()=>{if(live()){visit.remove=null;render('#shutter-title');}});
 root.querySelector('[data-shutter-confirm]')?.addEventListener('click',()=>{if(!visit.remove)return;const [kind,index]=visit.remove.split(':');act(()=>removeShutterRecord(state,kind,Number(index),ctx.canExport),'#shutter-title');});
}
